// ============================================================
// 智能匹配推送算法
// 根据岗位JD技能清单 + 用户学习进度 + 技能缺口 自动匹配资源
// ============================================================
export function findMatchingResources(positionKey, userProgress = 0, masteredSkills = []) {
  const posData = positionSkillData[positionKey]
  if (!posData) return []

  // 扁平化所有技能
  const allSkills = []
  for (const [, list] of Object.entries(posData.categories)) {
    for (const s of list) {
      allSkills.push(s)
    }
  }

  // 技能分级
  const mustSkills = allSkills.filter(s => s.level === 'must').map(s => s.name)
  const preferSkills = allSkills.filter(s => s.level === 'prefer').map(s => s.name)
  const bonusSkills = allSkills.filter(s => s.level === 'bonus').map(s => s.name)

  // 计算缺口技能（未掌握且必备/优先）
  const gapSkills = allSkills
    .filter(s => !masteredSkills.includes(s.name) && (s.level === 'must' || s.level === 'prefer'))
    .map(s => s.name)

  // 为每条资源计算匹配分数
  const scored = resourceDatabase.map(resource => {
    let score = 0
    const matchedSkills = []

    for (const tag of resource.skillTags) {
      if (mustSkills.some(s => tag.includes(s) || s.includes(tag))) {
        score += 10
        matchedSkills.push({ name: tag, level: 'must' })
      } else if (preferSkills.some(s => tag.includes(s) || s.includes(tag))) {
        score += 5
        matchedSkills.push({ name: tag, level: 'prefer' })
      } else if (bonusSkills.some(s => tag.includes(s) || s.includes(tag))) {
        score += 2
        matchedSkills.push({ name: tag, level: 'bonus' })
      }
    }

    // 缺口技能额外加分（推送优先级提升）
    const gapMatchCount = resource.skillTags.filter(tag =>
      gapSkills.some(g => tag.includes(g) || g.includes(tag))
    ).length
    score += gapMatchCount * 8

    // 覆盖率加成
    const skillCoverage = matchedSkills.length / Math.max(resource.skillTags.length, 1)
    score += skillCoverage * 5

    // 进度适配
    if (userProgress > 50 && resource.difficulty === '进阶') score += 2

    return { ...resource, score, matchedSkills, skillCoverage, gapMatchCount }
  })

  // 过滤排序
  const filtered = scored.filter(r => r.score > 0)
  filtered.sort((a, b) => {
    // 先按缺口匹配排序，再按总分
    if (b.gapMatchCount !== a.gapMatchCount) return b.gapMatchCount - a.gapMatchCount
    return b.score - a.score
  })

  // 精选6条
  const recommended = filtered.slice(0, 6)

  return recommended.map(item => ({
    id: item.id,
    title: item.title,
    type: item.type,
    typeLabel: typeLabels[item.type] || item.type,
    provider: item.provider,
    difficulty: item.difficulty,
    duration: item.duration,
    durationText: formatDuration(item.duration),
    description: item.description,
    rating: item.rating,
    students: item.students,
    externalUrl: item.externalUrl,
    skillTags: item.skillTags,
    matchedSkills: item.matchedSkills,
    practiceExercises: item.practiceExercises,
    recommendedTools: item.recommendedTools,
    score: item.score,
    gapMatchCount: item.gapMatchCount
  }))
}

// 格式化时长
export function formatDuration(minutes) {
  if (minutes < 60) return minutes + ' 分钟'
  if (minutes < 480) return Math.floor(minutes / 60) + ' 小时'
  return (minutes / 480).toFixed(1) + ' 天'
}

// 确保每项技能至少匹配一份资源
export function ensureSkillCoverage(positionKey) {
  const posData = positionSkillData[positionKey]
  if (!posData) return []

  const allSkillNames = []
  for (const [, list] of Object.entries(posData.categories)) {
    for (const s of list) {
      allSkillNames.push(s.name)
    }
  }

  const uncovered = []
  for (const name of allSkillNames) {
    const hasResource = resourceDatabase.some(r =>
      r.skillTags.some(tag => tag.includes(name) || name.includes(tag))
    )
    if (!hasResource) uncovered.push(name)
  }

  return uncovered
}

// 生成每日学习计划
export function generateDailyPlan(resources, dailyHours = 2) {
  const dailyMinutes = dailyHours * 60
  const plan = []
  let currentDay = []
  let currentMinutes = 0

  for (const r of resources) {
    if (currentMinutes + r.duration <= dailyMinutes * 2) {
      currentDay.push(r)
      currentMinutes += r.duration
    } else {
      if (currentDay.length > 0) plan.push({ items: currentDay, totalMinutes: currentMinutes })
      currentDay = [r]
      currentMinutes = r.duration
    }
  }
  if (currentDay.length > 0) plan.push({ items: currentDay, totalMinutes: currentMinutes })

  return plan
}
