const defaultResourceCards = []

const resourceCards = computed(() => {
  if (!selectedPosition.value) return defaultResourceCards
  const userProgress = parseInt(localStorage.getItem('learningProgress_' + selectedPosition.value) || '0', 10)
  let matched = findMatchingResources(selectedPosition.value, userProgress, masteredSkills.value)
  if (activeFilter.value === 'gap') {
    matched = matched.filter(r => r.gapMatchCount > 0)
  } else if (activeFilter.value === 'matched') {
    matched = matched.filter(r =>
      r.matchedSkills && r.matchedSkills.some(s => masteredSkills.value.some(m => m.includes(s.name) || s.name.includes(m)))
    )
  }
  if (!matched || matched.length === 0) return defaultResourceCards
  return matched
})

const currentSkills = computed(() => {
  if (!selectedPosition.value) return []
  return getAllSkills(selectedPosition.value)
})

const gapCount = computed(() => {
  if (!selectedPosition.value) return 0
  const all = diagnoseSkillGaps(selectedPosition.value, masteredSkills.value)
  return all.filter(s => s.needToLearn && (s.level === 'must' || s.level === 'prefer')).length
})

const selectedPositionLabel = computed(() => {
  if (!selectedPosition.value) return '未选择'
  for (const group of positionGroups) {
    const pos = group.positions.find(p => p.key === selectedPosition.value)
    if (pos) return pos.label
  }
  return '未选择'
})

const aiContext = computed(() => {
  const skills = currentSkills.value
  return {
    positionKey: selectedPosition.value,
    positionLabel: selectedPositionLabel.value,
    skills: skills,
    skillCount: skills.length,
    masteredCount: masteredSkills.value.length,
    gapCount: gapCount.value,
    viewingResource: currentViewingResource.value,
    placeholder: selectedPosition.value
      ? `问问${selectedPositionLabel.value}的学习路线、薪资、技能提升...`
      : '先选择岗位，我再为你规划'
  }
})

const goBack = () => {
  router.push('/dashboard')
}

const handleNavClick = (key) => {
  if (key === 'skill-route') {
    if (!selectedPosition.value) {
      alert('请先选择目标岗位')
      return
    }
    router.push('/skill-route')
  } else {
    currentNav.value = key
  }
}

const handleSkillSelect = (skillName) => {
