}

const handleFilterChange = (filter) => {
  activeFilter.value = filter
}

const handleResourceClick = (card) => {
  currentViewingResource.value = card.title
}

const handleStatusChange = ({ cardId, status }) => {
  console.log('Status changed:', cardId, status)
}

watch(selectedPosition, (val) => {
  if (val) {
    localStorage.setItem('selectedPosition', val)
    const saved = localStorage.getItem('masteredSkills_' + val)
    if (saved) {
      try { masteredSkills.value = JSON.parse(saved) } catch (e) { masteredSkills.value = [] }
    } else {
      masteredSkills.value = []
    }
  }
})

const drawBackground = () => {
  const canvas = bgCanvas.value
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  canvas.width = window.innerWidth
  canvas.height = window.innerHeight

  const particles = []
  const particleCount = 80
  for (let i = 0; i < particleCount; i++) {
    particles.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      size: Math.random() * 2 + 0.5,
      speedX: (Math.random() - 0.5) * 0.5,
      speedY: (Math.random() - 0.5) * 0.5,
      opacity: Math.random() * 0.5 + 0.2
    })
  }

  const animate = () => {
    ctx.fillStyle = 'rgba(10, 15, 25, 0.1)'
    ctx.fillRect(0, 0, canvas.width, canvas.height)

    particles.forEach(p => {
      p.x += p.speedX
      p.y += p.speedY
      if (p.x < 0 || p.x > canvas.width) p.speedX *= -1
      if (p.y < 0 || p.y > canvas.height) p.speedY *= -1

      ctx.beginPath()
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2)
      ctx.fillStyle = `rgba(74, 158, 255, ${p.opacity})`
      ctx.fill()
    })

    particles.forEach((p1, i) => {
      particles.slice(i + 1).forEach(p2 => {
        const dx = p1.x - p2.x
        const dy = p1.y - p2.y
        const dist = Math.sqrt(dx * dx + dy * dy)
        if (dist < 120) {
          ctx.beginPath()
          ctx.moveTo(p1.x, p1.y)
          ctx.lineTo(p2.x, p2.y)
          ctx.strokeStyle = `rgba(74, 158, 255, ${0.15 * (1 - dist / 120)})`
          ctx.lineWidth = 0.5
          ctx.stroke()
        }
      })
    })

    requestAnimationFrame(animate)
  }
  animate()
}

let animFrame = null

onMounted(() => {
  const saved = localStorage.getItem('selectedPosition')
  if (saved) {
    selectedPosition.value = saved
  }
  drawBackground()
  window.addEventListener('resize', () => {
    const canvas = bgCanvas.value
    if (canvas) {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }
  })
})

onUnmounted(() => {
  if (animFrame) cancelAnimationFrame(animFrame)
})
