// 扁平化获取所有技能列表（用于资源匹配）
export function getAllSkills(positionKey) {
  const posData = positionSkillData[positionKey]
  if (!posData) return []
  const skills = []
  for (const [category, list] of Object.entries(posData.categories)) {
    for (const skill of list) {
      skills.push({ ...skill, category })
    }
  }
  return skills
}

// 获取按学习顺序排序的技能列表
export function getSkillsByLearningOrder(positionKey) {
  const skills = getAllSkills(positionKey)
  return skills.sort((a, b) => a.order - b.order)
}

// 生成技能缺口诊断
// masteredSkills: 用户已掌握的技能名数组
// 返回：需要补强的技能列表（未掌握 + 必备/优先）
export function diagnoseSkillGaps(positionKey, masteredSkills) {
  const allSkills = getAllSkills(positionKey)
  return allSkills.map(skill => ({
    ...skill,
    mastered: masteredSkills.includes(skill.name),
    needToLearn: !masteredSkills.includes(skill.name)
  }))
}

// 获取岗位名称
export function getPositionName(positionKey) {
  return positionSkillData[positionKey]?.name || positionKey
}
