<template>
  <div class="skill-checklist">
    <div class="skill-section-header">
      <h3>📋 岗位JD技能清单</h3>
      <div class="skill-header-actions">
        <span class="skill-count">共 {{ totalSkillCount }} 项技能</span>
        <span class="gap-count" v-if="gapCount > 0">
          <span class="gap-icon">⚠️</span>
          {{ gapCount }} 项待掌握
        </span>
      </div>
    </div>

    <div class="skill-filter-bar">
      <button
        class="filter-btn"
        :class="{ active: activeFilter === 'all' }"
        @click="activeFilter = 'all'; $emit('filter-change', 'all')"
      >
        📚 全部资源
      </button>
      <button
        class="filter-btn"
        :class="{ active: activeFilter === 'gap' }"
        @click="activeFilter = 'gap'; $emit('filter-change', 'gap')"
      >
        🎯 仅缺口技能资源
      </button>
      <button
        class="filter-btn"
        :class="{ active: activeFilter === 'matched' }"
        @click="activeFilter = 'matched'; $emit('filter-change', 'matched')"
      >
        ✅ 已掌握技能
      </button>
    </div>

    <div class="skill-categories">
      <div v-for="category in categorizedSkills" :key="category.name" class="skill-category">
        <h4 class="category-title">
          <span class="category-name">{{ category.name }}</span>
          <span class="category-count">{{ category.skills.length }} 项</span>
        </h4>
        <div class="skill-tags">
          <div
            v-for="skill in category.skills"
            :key="skill.name"
            class="skill-tag-wrapper"
          >
            <label class="skill-tag" :class="['level-' + skill.level, { mastered: masteredSkills.includes(skill.name), selected: selectedSkill === skill.name }]">
              <input
                type="checkbox"
                :checked="masteredSkills.includes(skill.name)"
                @change="toggleMastered(skill.name)"
                class="skill-checkbox"
              />
              <span class="skill-name" @click.stop="selectSkill(skill.name)">
                {{ skill.name }}
              </span>
              <span class="level-badge">{{ levelLabels[skill.level] }}</span>
              <span class="heat-badge" :title="heatLabels[skill.heat]">
                {{ heatLabels[skill.heat] }}
              </span>
              <span class="stage-badge" :class="'stage-' + skill.stage">{{ stageLabels[skill.stage] }}</span>
              <span class="order-badge" v-if="skill.order">
                📖{{ skill.order }}
              </span>
            </label>
          </div>
        </div>
      </div>
    </div>

    <div class="skill-gap-summary" v-if="gapCount > 0">
      <h4>🔍 技能缺口诊断清单</h4>
      <div class="gap-items">
        <div v-for="skill in gapSkills" :key="skill.name" class="gap-item">
          <span class="gap-skill">{{ skill.name }}</span>
          <span class="gap-level">{{ levelLabels[skill.level] }}</span>
          <span class="gap-heat">{{ heatLabels[skill.heat] }}</span>
        </div>
      </div>
      <p class="gap-tip">💡 系统将优先推送匹配这些缺口技能的学习资源</p>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { heatLabels, levelLabels, stageLabels, getAllSkills, diagnoseSkillGaps } from '@/data/skillData.js'

const props = defineProps({
  positionKey: { type: String, default: '' },
  masteredSkills: { type: Array, default: () => [] }
})

const emit = defineEmits(['update:masteredSkills', 'skill-select', 'filter-change'])

const activeFilter = ref('all')
const selectedSkill = ref('')

const categorizedSkills = computed(() => {
  if (!props.positionKey) return []
  const skills = getAllSkills(props.positionKey)
  const groups = {}
  for (const s of skills) {
    if (!groups[s.category]) groups[s.category] = { name: s.category, skills: [] }
    groups[s.category].skills.push(s)
  }
  return Object.values(groups)
})

const totalSkillCount = computed(() => {
  return categorizedSkills.value.reduce((sum, g) => sum + g.skills.length, 0)
})

const gapCount = computed(() => gapSkills.value.length)

const gapSkills = computed(() => {
  if (!props.positionKey) return []
  const all = diagnoseSkillGaps(props.positionKey, props.masteredSkills)
  return all.filter(s => s.needToLearn && (s.level === 'must' || s.level === 'prefer'))
})

function toggleMastered(skillName) {
  const newList = [...props.masteredSkills]
  const idx = newList.indexOf(skillName)
  if (idx >= 0) newList.splice(idx, 1)
  else newList.push(skillName)
  emit('update:masteredSkills', newList)
  localStorage.setItem('masteredSkills_' + props.positionKey, JSON.stringify(newList))
}

function selectSkill(skillName) {
  selectedSkill.value = selectedSkill.value === skillName ? '' : skillName
  emit('skill-select', selectedSkill.value)
}
</script>

