              v-for="(key, label) in statusOptions"
              :key="key"
              class="status-btn"
              :class="{ active: getLearningStatus(card.id) === key }"
              @click="setStatus(card.id, key)"
            >
              {{ label }}
            </button>
          </div>
        </div>
      </div>
