<script setup>
import { ref, computed } from 'vue'
import { learningStatusLabels, generateDailyPlan } from '@/data/resources.js'

const props = defineProps({
  cards: { type: Array, default: () => [] },
  positionKey: { type: String, default: '' }
})

const emit = defineEmits(['resource-click', 'status-change'])

const expandedCards = ref([])

const statusOptions = [
  ['not_started', '未学习'],
  ['in_progress', '学习中'],
  ['completed', '已完成']
]

const dailyPlan = computed(() => {
  const plan = generateDailyPlan(props.cards, 2)
  return plan
})

const dailyMinutes = computed(() => {
  if (dailyPlan.value.length === 0) return 120
  const total = dailyPlan.value.reduce((s, d) => s + d.totalMinutes, 0)
  return Math.round(total / dailyPlan.value.length / 60) * 60
})

function toggleExpand(cardId) {
  const idx = expandedCards.value.indexOf(cardId)
  if (idx >= 0) expandedCards.value.splice(idx, 1)
  else expandedCards.value.push(cardId)
}

function openResource(card) {
  if (!card.externalUrl) return
  window.open(card.externalUrl, '_blank', 'noopener')
  setStatus(card.id, 'in_progress')
  emit('resource-click', card)
}

function openTool(tool) {
  if (tool.url) window.open(tool.url, '_blank', 'noopener')
}

function getLearningStatus(cardId) {
  const statusKey = `learningStatus_${props.positionKey}`
  const saved = JSON.parse(localStorage.getItem(statusKey) || '{}')
  return saved[cardId] || 'not_started'
}

function setStatus(cardId, status) {
  const statusKey = `learningStatus_${props.positionKey}`
  const saved = JSON.parse(localStorage.getItem(statusKey) || '{}')
  saved[cardId] = status
  localStorage.setItem(statusKey, JSON.stringify(saved))
  emit('status-change', { cardId, status })
}

function getMatchedSkillsText(card) {
  if (!card.matchedSkills) return ''
  const names = card.matchedSkills.map(s => s.name)
  if (names.length <= 3) return names.join('、')
  return names.slice(0, 3).join('、') + ` 等${names.length}项`
}
</script>

